import requests

def compare_weather(cities, api_key):
    results = []
    hottest = None
    coldest = None
    avg_temp = 0

    for city in cities:
        try:
            response = requests.get(f"https://api.openweathermap.org/data/2.5/weather", params={"q": city, "appid": api_key, "units": "metric"})
            data = response.json()
            results.append({
                "city": city,
                "temperature": data["main"]["temp"],
                "feels_like": data["main"]["feels_like"],
                "humidity": data["main"]["humidity"],
                "description": data["weather"][0]["description"],
                "wind_speed": data["wind"]["speed"]
            })
            if not hottest or data["main"]["temp"] > hottest["temperature"]:
                hottest = {
                    "city": city,
                    "temperature": data["main"]["temp"]
                }
            if not coldest or data["main"]["temp"] < coldest["temperature"]:
                coldest = {
                    "city": city,
                    "temperature": data["main"]["temp"]
                }
            avg_temp += data["main"]["temp"]
        except requests.exceptions.RequestException:
            pass

    if not results:
        return {"error": "No data available", "results": []}

    return {
        "results": results,
        "hottest": hottest,
        "coldest": coldest,
        "avg_temp": avg_temp / len(results)
    }
```
