import requests

def compare_weather(cities, api_key):
    results = []
    hottest = None
    coldest = None
    avg_temp = 0

    for city in cities:
        try:
            response = requests.get(
                "https://api.openweathermap.org/data/2.5/weather",
                params={
                    "q": city,
                    "appid": api_key,
                    "units": "metric"
                }
            )
